// Genera rotacion 4x3 (4 dias trabajo / 3 descanso) por operador
const operadores = ['Equipo A','Equipo B','Equipo C','Equipo D'];
const turnos = ['Manana (07-15)','Tarde (15-23)','Noche (23-07)'];
const out = [];
const inicio = new Date();
for (let d = 0; d < 7; d++) {
  const fecha = new Date(inicio); fecha.setDate(inicio.getDate() + d);
  turnos.forEach((t, ti) => {
    const eq = operadores[(d + ti) % operadores.length];
    out.push({ fecha: fecha.toISOString().slice(0,10), turno: t, equipo: eq });
  });
}
return out.map(r => ({ json: r }));
